WITH joined_data AS (SELECT s.fundingtype, sa.avgscrread, sa.avgscrmath, sa.avgscrwrite, sa.enroll12 FROM satscores sa INNER JOIN schools s ON sa.cds = s.cdscode WHERE s.fundingtype IS NOT NULL AND s.virtual IS NOT NULL) SELECT fundingtype, AVG(avgscrread) as avg_read, AVG(avgscrmath) as avg_math, AVG(avgscrwrite) as avg_write, AVG(enroll12) as avg_enrollment FROM joined_data GROUP BY fundingtype ORDER BY avg_read DESC;
